"""Verify the explicit period-28 valuation table against direct computation."""
from __future__ import annotations
from collections import defaultdict


def perrin(n_max: int) -> list[int]:
    R: list[int] = [3, 0, 2]
    for i in range(3, n_max + 1):
        R.append(R[i - 2] + R[i - 3])
    return R


def v2(x: int) -> int:
    x = abs(x)
    k = 0
    while x % 2 == 0:
        x //= 2
        k += 1
    return k


def perrin_nu(r: int) -> int:
    r %= 28
    if r in {0, 3, 7, 13, 14, 17, 21, 27}:
        return 1
    if r in {5, 6, 12, 20, 24}:
        return 2
    return 0


def main() -> None:
    R = perrin(2000)
    exceptional = {10, 19, 26}
    seen: dict[int, set[int]] = defaultdict(set)
    for m in range(1, 2000):
        seen[m % 28].add(v2(R[m] - 1))
    for r in range(28):
        vals = sorted(seen[r])
        if r in exceptional:
            print(f"r={r:2d}  observed {vals}  (exceptional, unbounded)")
        else:
            ok = vals == [perrin_nu(r)]
            print(f"r={r:2d}  observed {vals}  predicted {perrin_nu(r)}  ok={ok}")


if __name__ == "__main__":
    main()

"""Show the period-56 self-similar split of the three exceptional classes."""
from __future__ import annotations
from collections import defaultdict


def perrin(n_max: int) -> list[int]:
    R: list[int] = [3, 0, 2]
    for i in range(3, n_max + 1):
        R.append(R[i - 2] + R[i - 3])
    return R


def v2(x: int) -> int:
    x = abs(x); k = 0
    while x % 2 == 0:
        x //= 2; k += 1
    return k


def main() -> None:
    R = perrin(6000)
    obs: dict[int, set[int]] = defaultdict(set)
    for m in range(1, 6000):
        obs[m % 56].add(v2(R[m] - 1))
    pairs = {10: (38, 10), 19: (47, 19), 26: (26, 54)}
    for parent, (exact3, persist) in pairs.items():
        e = sorted(obs[exact3]); p = sorted(obs[persist])
        print(f"parent {parent} mod 28:")
        print(f"   m={exact3:2d} mod 56 -> {e}  (locks at 3)")
        print(f"   m={persist:2d} mod 56 -> {p}  (>= 4, keeps refining)")


if __name__ == "__main__":
    main()

"""Perrin-Brocard sieve: odd valuation excludes squares; search for solutions."""
from __future__ import annotations
from math import isqrt


def perrin(n_max: int) -> list[int]:
    R: list[int] = [3, 0, 2]
    for i in range(3, n_max + 1):
        R.append(R[i - 2] + R[i - 3])
    return R


def perrin_nu(r: int) -> int:
    r %= 28
    if r in {0, 3, 7, 13, 14, 17, 21, 27}:
        return 1
    if r in {5, 6, 12, 20, 24}:
        return 2
    return 0


def is_square(y: int) -> bool:
    if y < 0:
        return False
    r = isqrt(y)
    return r * r == y


def main() -> None:
    excluded = sorted(r for r in range(28)
                      if r not in {10, 19, 26} and perrin_nu(r) % 2 == 1)
    print("residues mod 28 killed by odd valuation (v2=1):", excluded)
    R = perrin(5000)
    hits = [m for m in range(3, 5000) if is_square(R[m] - 1)]
    print("m < 5000 with R_m - 1 a perfect square:", hits)


if __name__ == "__main__":
    main()

