function perrin_brocard_solutions(N):
    odd_val <- {0,3,7,13,14,17,21,27}
    solutions <- empty list
    for m in 3 .. N-1:
        if (m mod 28) in odd_val: continue   # sieved by odd valuation
        y <- R_m - 1
        if y >= 0 and isqrt(y)^2 == y: append m
    return solutions
